/* Cursor movements */
/* Note to overlay tinkerers.  The placement of this overlay controls the
   location of the function xputc().  This function is not currently in
   trampoli.[ch] files for what is deemed to be performance reasons.  If
   this define is moved and or xputc() is taken out of the ROOT overlay,
   then action must be taken in trampoli.[ch]. */
function term_end_screen()
{
    
    term_clear_screen();
    xputs(C.VE);
    xputs(C.TE);
}

function nocmov(x,y)
{
    x=C.int(x);y=C.int(y);
    if (C.int( C.ttyDisplay.cury) > y) {
        if (C.UP) {
            while (C.int( C.ttyDisplay.cury) > y) { /* Go up. */
                xputs(C.UP);
                C.ttyDisplay.cury--;
            }
        } else if (C.nh_CM) {
            cmov(x, y);
        } else if (C.HO) {
            home();
            C.tty_curs(C.BASE_WINDOW, x + 1, y);
        } /* else impossible("..."); */
    } else if (C.int( C.ttyDisplay.cury) < y) {
        if (C.XD) {
            while (C.int( C.ttyDisplay.cury) < y) {
                xputs(C.XD);
                C.ttyDisplay.cury++;
            }
        } else if (C.nh_CM) {
            cmov(x, y);
        } else {
            while (C.int( C.ttyDisplay.cury) < y) {
                void (xputc(10));
                C.ttyDisplay.curx = C.short(0);
                C.ttyDisplay.cury++;
            }
        }
    }
    if (C.int( C.ttyDisplay.curx) < x) { /* Go to the right. */
        if (!C.nh_ND) {
            cmov(x, y);
        } else { /* bah */
             /* should instead print what is there already */
            while (C.int( C.ttyDisplay.curx) < x) {
                xputs(C.nh_ND);
                C.ttyDisplay.curx++;
            }
        }
    } else if (C.int( C.ttyDisplay.curx) > x) {
        while (C.int( C.ttyDisplay.curx) > x) { /* Go to the left. */
            xputs(C.BC);
            C.ttyDisplay.curx--;
        }
    }
}

/* See note above.  xputc() is a special function for overlays. */
function cmov(x,y)
{
    x=C.int(x);y=C.int(y);
    xputs(C.tgoto(C.nh_CM, x, y));
    C.ttyDisplay.cury = C.short(y);
    C.ttyDisplay.curx = C.short(x);
}

/* actually char, but explicitly specify its widened type */
/* In-band sync markers for screen recording.
 *
 * When NOMUX_MARKERS=1 is set in the environment, NetHack emits OSC
 * sequences to stdout at every input-wait boundary (and once at game
 * end after topten output), each carrying the rendered screen state
 * for that boundary.  A recorder reading stdout parses these markers
 * and uses the embedded screen as the captured frame for the step.
 *
 * Marker wire format:
 *   ESC ] 7777 ; KIND=input ; SEQ=N ; CX=cx ; CY=cy ; LEN=L BEL
 *   <L bytes of screen content>
 *
 * The OSC body up through BEL contains only printable ASCII so the
 * recorder can parse it unambiguously.  The L payload bytes that
 * follow are the rendered screen serialization (escape-sequences
 * preserved verbatim, no encoding) and may contain arbitrary bytes
 * including ESC.  The recorder reads exactly L bytes after the BEL.
 *
 * KIND=input fires at tty_nhgetch / tty_nh_poskey blocking points and
 * once at nh_terminate (post-topten final frame).  KIND=anim fires
 * for intermediate animation frames (zap beams, knockback, thrown
 * objects); these don't bump SEQ since they aren't input boundaries.
 *
 * When NOMUX_MARKERS is unset the emit is a no-op — the binary plays
 * normally with no extra stdout output. */
function xputc(c)
{
    c=C.int(c);
    /*
     * Note:  xputc() as a direct all to putchar() doesn't make any
     * sense _if_ putchar() is a function.  But if it is a macro, an
     * overlay configuration would want to avoid hidden code bloat
     * from multiple putchar() expansions.  And it gets passed as an
     * argument to tputs() so we have to guarantee an actual function
     * (while possibly lacking ANSI's (func) syntax to override macro).
     *
     * xputc() used to be declared as 'void xputc(c) char c; {}' but
     * avoiding the proper type 'int' just to avoid (void) casts when
     * ignoring the result can't have been sufficient reason to add it.
     * It also had '#if apollo' conditional to have the arg be int.
     * Matching putchar()'s declaration and using explicit casts where
     * warranted is more robust, so we're just a jacket around that.
     */
    return C.int(C.putchar(c));
}

/* Emit a single in-band marker carrying the current rendered screen.
 * KIND distinguishes input boundaries from animation frames. */
function nomux_markers_enabled()
{
    
    
    if (C.state.markers_cached < 0) {
        let ev = C.charPointer(C.getenv("NOMUX_MARKERS"));
        C.state.markers_cached = C.int((Number(Boolean(ev && C.HEAP8[C.charPointer(ev)] && C.HEAP8[C.charPointer(ev) + Number(0)] != 48))) ? 1 : 0);
    }
    return C.int(C.state.markers_cached);
}

/* Called for intermediate animation frames: zap beams, hurtle/knockback
 * steps, thrown-object trajectories, etc.  Bumps the per-animation id
 * but NOT the input-boundary SEQ. */
function nomux_emit_marker(kind)
{
    
    if (!nomux_markers_enabled())
        return;

    {
        let scr = C.charPointer(nomux_capture_screen());
        let cx; let cy;
        let scr_len = C.ulong(scr ? C.strlen(scr) : 0);
        nomux_get_cursor(C.localPointer("int",()=>cx,_value=>cx=_value), C.localPointer("int",()=>cy,_value=>cy=_value));
                     
        C.fflush(C.NULL);
        C.teleport_capture(scr, cx, cy, !C.strcmp(kind, "anim"));
        return;
      
        C.fprintf(C.stdout, "\u001b]7777;KIND=%s;SEQ=%d;ANIM=%d;CX=%d;CY=%d;LEN=%zu\u0007",
                kind, C.nomux_seq, C.nomux_anim_id, cx, cy, scr_len);
        if (scr_len > 0)
            C.fwrite(scr, 1, scr_len, C.stdout);
        C.fflush(C.stdout);
    }
}

/* Called at every real input-wait boundary (tty_nhgetch, tty_nh_poskey)
 * and once at nh_terminate after topten — the points where one
 * authoritative frame should be captured per step.  Bumps SEQ. */
function nomux_capture_write_screen()
{
    
    C.nomux_anim_id++;
    nomux_emit_marker("anim");
}

/* NOMUX shadow frame buffer implementation */
function nomux_capture_write_input_boundary()
{
    
    C.nomux_seq++;
    nomux_emit_marker("input");
}

function nomux_clear_screen()
{
    const cells = C.nomuxScreenViews().bytes;
    for (let at = 0; at < 24 * 80 * 4; at += 4) {
        cells[at] = 32; cells[at + 1] = 7;
        cells[at + 2] = 0; cells[at + 3] = 0;
    }
}

function nomux_clear_to_eol(row,col)
{
    row=C.int(row);col=C.int(col);
    let c;
    const cells = C.nomuxScreenViews().bytes;
    if (Number(Boolean(row < 0 || row >= 24))) return;
    for (c = C.int((col < 0 ? 0 : col)); c < 80; c++) {
        cells[(row * 80 + c) * 4 + 0] = 32;
        cells[(row * 80 + c) * 4 + 1] = 7;
        cells[(row * 80 + c) * 4 + 2] = 0;
        /* Reset decgfx too: cl_end's job is to wipe a region, and a
         * cleared cell shouldn't carry a graphics-mode flag from
         * whatever character occupied that position before. Without
         * this, leftover decgfx from the prior screen's map glyphs
         * (walls, floors) leaks into menu indent columns and shows
         * up in the wire as ESC-N space ESC-O around an otherwise
         * blank cell — visually identical to a regular space, but
         * not byte-equal across rebuilds or when comparing against
         * a JS port that clears decgfx on every overwrite. */
        cells[(row * 80 + c) * 4 + 3] = 0;
    }
}

function nomux_putch(ch)
{
    ch=C.int(ch);
    let row; let col;
    if (Number(Boolean(!C.ttyDisplay || ch < 32))) return;
    row = C.int(C.ttyDisplay.cury);
    col = C.int(C.ttyDisplay.curx);
    if (Number(Boolean(row >= 0 && row < 24 && col >= 0 && col < 80))) {
        const cells = C.nomuxScreenViews().bytes;
        const at = (row * 80 + col) * 4;
        cells[at] = ch;
        cells[at + 1] = C.nomux_fg_cur;
        cells[at + 2] = C.nomux_attr_cur;
        cells[at + 3] = C.nomux_decgfx_cur;
    }
}

function nomux_set_attr(attr)
{
    attr=C.int(attr);
    switch (attr) {
    case C.ATR_INVERSE: C.nomux_attr_cur = C.uchar(C.int(C.int(C.nomux_attr_cur) | C.int(1))); break;
    case C.ATR_BOLD:    C.nomux_attr_cur = C.uchar(C.int(C.int(C.nomux_attr_cur) | C.int(2))); break;
    case C.ATR_ULINE:   C.nomux_attr_cur = C.uchar(C.int(C.int(C.nomux_attr_cur) | C.int(4))); break;
    }
}

function nomux_end_attr()
{
     C.nomux_attr_cur = C.uchar(0); }

function nomux_set_fg(color)
{
    color=C.int(color);
    /* Mirror C's wc2_darkgray remap: when that option is on,
     * hilites[CLR_BLACK] is wired to BRIGHT_BLACK so the terminal
     * receives [90m instead of [30m (plain black is invisible
     * against a black background).  The shadow buffer must track
     * the *visible* color, not the nominal index, or the capture
     * will diverge from what the terminal (and JS) sees. */
    if (Number(Boolean(color == C.CLR_BLACK && C.iflags.wc2_darkgray)))
        color = C.int(8);  /* index 8 -> ANSI 90m (bright black / dark gray) */
    C.nomux_fg_cur = C.uchar((Number(Boolean(color < 0 || color >= 16))) ? 7 : C.uchar( color));
}

function nomux_end_fg()
{
     C.nomux_fg_cur = C.uchar(7); }

function nomux_sgr_fg(fg)
{
    fg=C.int(fg);
    if (Number(Boolean(fg >= 0 && fg <= 7))) return C.int(30 + fg);
    if (Number(Boolean(fg >= 8 && fg <= 15))) return C.int(90 + (fg - 8));
    return C.int(37);
}

/* Raw-mode shadow tracking for tty_raw_print / tty_raw_print_bold output.
 * The C code calls these directly via puts() and fputs(), bypassing the
 * normal wintty rendering pipeline (no tty_putsym/tty_putstr indirection).
 * The default end-of-game high-score panel (topten() with iflags.toptenwin
 * == FALSE) goes through this path entirely, so without these hooks the
 * NOMUX shadow buffer is blind to it.
 *
 * Raw mode is entered on the first raw_print after ttyDisplay is gone
 * (typical post-exit_nhwindows endgame sequence) or by an explicit call
 * to nomux_enter_raw_mode(). It uses its own row/col counters because
 * ttyDisplay is null at this point.
 */
function nomux_capture_screen()
{
    
    let p = C.charPointer(C.nomux_out);
    let screen = C.nomuxScreenViews();
    let row; let col; let end; let cur_fg; let cur_attr;
    /* tmux capture-pane -e format:
     * - Color start: \033[97m (just the code, no 0; prefix)
     * - Color end (to default): \033[39m (fg reset only)
     * - Attr start: \033[7m (inverse), \033[1m (bold)
     * - Attr end: \033[27m (end inverse), \033[22m (end bold)
     * - Full reset: \033[0m only at end-of-line or when both attr+color reset
     * Incremental: only emit what changes between cells. */
    for (row = C.int(0); row < 24; row++) {
        screen = C.nomuxScreenViews();
        cur_fg = C.int(7); cur_attr = C.int(0);
        end = C.int(79);
        while (Number(Boolean(end >= 0
               && (screen.signed[(row * 80 + end) * 4] == 32 || screen.signed[(row * 80 + end) * 4] == 0)
               && screen.bytes[(row * 80 + end) * 4 + 2] == 0
               && (screen.bytes[(row * 80 + end) * 4 + 1] == 7 || screen.bytes[(row * 80 + end) * 4 + 1] == 0))))
            end--;
        let in_dec = C.int(0);
        for (col = C.int(0); col <= end; col++) {
            const cell = (row * 80 + col) * 4;
            let ch = screen.signed[cell] || 32;
            let fg = screen.bytes[cell + 1] || 7;
            let at = screen.bytes[cell + 2];
            const mayFormat = at != cur_attr || fg != cur_fg;
            /* Emit incremental SGR changes */
            if (at != cur_attr) {
                /* Handle attr changes individually */
                if (Number(Boolean((at & 1) && !(cur_attr & 1)))) p = C.charPointer(p) + Number(C.sprintf(p, "\u001b[7m"));
                if (Number(Boolean(!(at & 1) && (cur_attr & 1)))) p = C.charPointer(p) + Number(C.sprintf(p, "\u001b[27m"));
                if (Number(Boolean((at & 2) && !(cur_attr & 2)))) p = C.charPointer(p) + Number(C.sprintf(p, "\u001b[1m"));
                if (Number(Boolean(!(at & 2) && (cur_attr & 2)))) p = C.charPointer(p) + Number(C.sprintf(p, "\u001b[22m"));
                if (Number(Boolean((at & 4) && !(cur_attr & 4)))) p = C.charPointer(p) + Number(C.sprintf(p, "\u001b[4m"));
                if (Number(Boolean(!(at & 4) && (cur_attr & 4)))) p = C.charPointer(p) + Number(C.sprintf(p, "\u001b[24m"));
                cur_attr = C.int(at);
            }
            if (fg != cur_fg) {
                if (fg == 7) {
                    p = C.charPointer(p) + Number(C.sprintf(p, "\u001b[39m")); /* reset fg to default */
                } else {
                    p = C.charPointer(p) + Number(C.sprintf(p, "\u001b[%dm", nomux_sgr_fg(fg)));
                }
                cur_fg = C.int(fg);
            }
            // sprintf may call a provider which grows/replaces the heap.
            if (mayFormat) screen = C.nomuxScreenViews();
            const decgfx = screen.bytes[cell + 3];
            if (Number(Boolean(decgfx && !in_dec))) { screen.heap8[p++] = 14; in_dec = C.int(1); }
            else if (Number(Boolean(!decgfx && in_dec))) { screen.heap8[p++] = 15; in_dec = C.int(0); }
            screen.heap8[p++] = ch;
        }
        if (in_dec) { screen.heap8[p++] = 15; in_dec = C.int(0); }
        /* End-of-line: reset to defaults — match tmux format */
        if (Number(Boolean(cur_attr && cur_fg != 7))) {
            p = C.charPointer(p) + Number(C.sprintf(p, "\u001b[0m"));  /* both attr+color: full reset */
        } else if (cur_attr) {
            p = C.charPointer(p) + Number(C.sprintf(p, "\u001b[0m"));  /* attr only: full reset */
        } else if (cur_fg != 7) {
            p = C.charPointer(p) + Number(C.sprintf(p, "\u001b[39m")); /* color only: fg reset */
            cur_fg = C.int(7); cur_attr = C.int(0);
        }
        screen = C.nomuxScreenViews();
        if (row < 23) screen.heap8[p++] = 10;
    }
    screen.heap8[p] = 0;
    return C.nomux_out;
}

function nomux_enter_raw_mode()
{
    
    C.nomux_raw_active = C.int(1);
    C.nomux_raw_row = C.int(0);
    C.nomux_raw_col = C.int(0);
    /* exit_nhwindows / settty switch off alt-screen, so the visible
     * terminal returns to a blank main-screen state before the high-score
     * lines print. Mirror that by clearing the shadow. */
    nomux_clear_screen();
}

/* Write a string emitted by tty_raw_print / tty_raw_print_bold to the
 * shadow buffer, then bump SEQ so the harness re-reads the file.
 * If raw mode is not yet active and ttyDisplay is gone, enter raw mode
 * automatically (typical endgame path).
 *
 * Under NOMUX_MARKERS we have no tmux fallback, so we ALSO enter raw
 * mode when ttyDisplay is still alive — otherwise tty_suspend_nhwindows
 * goodbye strings ("Be seeing you...", "Saving...") arrive before
 * ttyDisplay is freed and would never reach the shadow buffer.
 *
 * BUT we skip *empty* raw_prints while ttyDisplay is alive: those are
 * flush/separator calls (pline-flushers, tty_raw_print_bold("") visual
 * spacing) that the tmux capture path also discarded. Treating them as
 * content would shift end-of-game output (topten) down by a row. */
function nomux_raw_putch(ch)
{
    ch=C.int(ch);
    if (ch == 10) {
        C.nomux_raw_row++;
        C.nomux_raw_col = C.int(0);
        return;
    }
    if (ch < 32) return;
    if (Number(Boolean(C.nomux_raw_row >= 0 && C.nomux_raw_row < 24
        && C.nomux_raw_col >= 0 && C.nomux_raw_col < 80))) {
        const cells = C.nomuxScreenViews().bytes;
        const at = (C.nomux_raw_row * 80 + C.nomux_raw_col) * 4;
        cells[at] = ch;
        cells[at + 1] = C.nomux_fg_cur;
        cells[at + 2] = C.nomux_attr_cur;
        cells[at + 3] = C.nomux_decgfx_cur;
    }
    C.nomux_raw_col++;
}

function nomux_raw_emit(s,bold)
{
    bold=C.int(bold);
    if (!C.nomux_raw_active) {
        if (Number(Boolean(C.ttyDisplay && (!C.HEAP8[C.charPointer(s)] || !nomux_markers_enabled()))))
            return;  /* in-game flush, or no-marker mode → skip */
        nomux_enter_raw_mode();
    }
    if (bold) C.nomux_attr_cur = C.uchar(C.int(C.int(C.nomux_attr_cur) | C.int(2)));
    for (let p = C.charPointer(s); C.HEAP8[C.charPointer(p)]; p++)
        nomux_raw_putch(C.int(C.uchar(C.HEAP8[C.charPointer(p)])));
    nomux_raw_putch(10);  /* puts() / tty_raw_print_bold both append a newline */
    if (bold) C.nomux_attr_cur = C.uchar(0);
    /* INTENTIONALLY do NOT call nomux_capture_write_input_boundary() here.
     *
     * The Python harness side (run_session.py:wait_for_nomux_advance)
     * waits for SEQ to advance past prev_seq, then reads the screen file.
     * If raw_emit bumps SEQ on EVERY call, the harness sees SEQ advance
     * after the FIRST emit and proceeds to read the screen — capturing
     * INTERMEDIATE topten output (e.g. blank-only-emitted, before
     * "You made the top ten list!" is written). This produced a
     * non-deterministic 1-blank vs 2-blank pattern in seed0030 segs
     * 1/2/5/7 (issue #460). Adding a tiny I/O delay here (an fopen+fclose
     * for debug) was enough to consistently shift to 1-blank for all
     * segments — confirming the race.
     *
     * Letting the next tty_nhgetch / tty_nh_poskey call's
     * nomux_capture_write_input_boundary fire is not enough at game-end
     * because there's no further input wait after topten — the next
     * thing is nh_terminate(). So we add a single write at nh_terminate
     * (see src/end.c) to capture the final state once topten has
     * finished emitting. */
}

function nomux_raw_emit_eol()
{
    
    if (C.nomux_raw_active) nomux_raw_putch(10);
}

/* NOMUX_CAPTURE */
function nomux_get_cursor(cx,cy)
{
    
    if (C.nomux_raw_active) {
        (cx).value = C.int(C.nomux_raw_col);
        (cy).value = C.int(C.nomux_raw_row);
        return;
    }
    (cx).value = C.int(C.ttyDisplay ? C.ttyDisplay.curx : 0);
    (cy).value = C.int(C.ttyDisplay ? C.ttyDisplay.cury : 0);
}

function xputs(s)
{
    
               
                            
     
    C.tputs(s, 1, xputc);
      
}

function cl_end()
{
    
    if (C.CE) {
        xputs(C.CE);
                    
        nomux_clear_to_eol(C.ttyDisplay.cury, C.ttyDisplay.curx);
      
    } else { /* no-CE fix - free after Harold Rynes */
        let cx = C.int(C.ttyDisplay.curx + 1);

        /* this looks terrible, especially on a slow terminal
           but is better than nothing */
        while (cx < C.CO) {
            void (xputc(32));
            cx++;
        }
        C.tty_curs(C.BASE_WINDOW, C.int( C.ttyDisplay.curx) + 1,
                 C.int( C.ttyDisplay.cury));
    }
}

function term_clear_screen()
{
    
    /* note: if CL is null, then termcap initialization failed,
     * so don't attempt screen-oriented I/O during final cleanup.
     */
    if (C.CL) {
        xputs(C.CL);
        home();
        /* set remembered data to all spaces */
                    
        nomux_clear_screen();
      
        C.erase_tty_screen();
    }
}

function home()
{
    
    if (C.HO)
        xputs(C.HO);
    else if (C.nh_CM)
        xputs(C.tgoto(C.nh_CM, 0, 0));
    else
        C.tty_curs(C.BASE_WINDOW, 1, 0); /* using UP ... */
    C.ttyDisplay.curx = C.short(C.ttyDisplay.cury = C.short(0));
}

function standoutbeg()
{
    
    if (C.SO)
        xputs(C.SO);
}

/* if you need one of these, uncomment it (here and in extern.h) */
/* not in most termcap entries */
/*0*/
function standoutend()
{
    
    if (C.SE)
        xputs(C.SE);
}

function backsp()
{
    
    xputs(C.BC);
}

function tty_nhbell()
{
    
    if (C.flags.silent)
        return;
    void (C.putchar(7)); /* curx does not change */
    void (C.fflush(C.stdout));
}

function graph_on()
{
    
                    
    C.nomux_decgfx_cur = C.uchar(1);
      
    if (C.AS)
        xputs(C.AS);
}

/* from termcap */
/* from termcap */
/* delay 50 ms */
function graph_off()
{
    
                    
    C.nomux_decgfx_cur = C.uchar(0);
      
    if (C.AE)
        xputs(C.AE);
}

/* must only be called with curx = 1 */
function tty_delay_output()
{
    
                  
          
      
    
    let no_delay_env;

    if (C.state.delay_no_delay < 0) {
        no_delay_env = C.charPointer(C.getenv("NETHACK_NO_DELAY"));
        if (Number(Boolean(!no_delay_env || !C.HEAP8[C.charPointer(no_delay_env)])))
            no_delay_env = C.charPointer(C.getenv("WEBHACK_NO_DELAY"));
        C.state.delay_no_delay = C.int((Number(Boolean(no_delay_env && C.HEAP8[C.charPointer(no_delay_env)] && C.HEAP8[C.charPointer(no_delay_env)] != 48))));
    }
    if (Number(Boolean(C.state.delay_no_delay || C.iflags.debug_fuzzer))) {
        void (C.fflush(C.stdout));
                    
        /* Capture the current screen at this animation boundary.
           This lets the session recorder see intermediate display
           states (zap beams, thrown objects, explosions) that would
           otherwise be invisible because the delay is suppressed.
           nomux_capture_write_screen appends to the anim log and
           bumps nomux_anim_id, which we include in the event marker
           so the appendix entry can be cross-referenced. */
        nomux_capture_write_screen();
      
        return;
    }
                  
                    
                              
                    /* sleep for 50 milliseconds */
               
     
      
                  
    /* simulate the delay with "cursor here" */
                             
                                                 
                              
     
      /* MICRO */
    /* BUG: if the padding character is visible, as it is on the 5620
       then this looks terrible. */
    if (C.flags.null) {
        C.tputs(
               
              "$<50>",
     
                   
      
              1, xputc);

    } else if (Number(Boolean(C.ospeed > 0 && C.ospeed < C.SIZE(C.tmspc10) && C.nh_CM))) {
        /* delay by sending cm(here) an appropriate number of times */
        let cmlen = C.int(C.int( C.strlen(C.tgoto(C.nh_CM, C.ttyDisplay.curx, C.ttyDisplay.cury))));
        let i = C.int(500 + Math.trunc((C.tmspc10[C.ospeed]) / (2)));

        while (i > 0) {
            cmov(C.int( C.ttyDisplay.curx), C.int( C.ttyDisplay.cury));
            i = C.int(C.int(C.int(i) - C.int(cmlen * C.tmspc10[C.ospeed])));
        }
    }
       /* MICRO */
}

/* free after Robert Viduya */
/*
 * Sets up color highlighting, using terminfo(4) escape sequences.
 *
 * Having never seen a terminfo system without curses, we assume this
 * inclusion is safe.  On systems with color terminfo, it should define
 * the 8 COLOR_FOOs, and avoid us having to guess whether this particular
 * terminfo uses BGR or RGB for its indexes.
 *
 * If we don't get the definitions, then guess.  Original color terminfos
 * used BGR for the original Sf (setf, Standard foreground) codes, but
 * there was a near-total lack of user documentation, so some subsequent
 * terminfos, such as early Linux ncurses and SCO UNIX, used RGB.  Possibly
 * as a result of the confusion, AF (setaf, ANSI Foreground) codes were
 * introduced, but this caused yet more confusion.  Later Linux ncurses
 * have BGR Sf, RGB AF, and RGB COLOR_FOO, which appears to be the SVR4
 * standard.  We could switch the colors around when using Sf with ncurses,
 * which would help things on later ncurses and hurt things on early ncurses.
 * We'll try just preferring AF and hoping it always agrees with COLOR_FOO,
 * and falling back to Sf if AF isn't defined.
 *
 * In any case, treat black specially so we don't try to display black
 * characters on the assumed black background.
 */
/* `curses' is aptly named; various versions don't like these
    macros used elsewhere within nethack; fortunately they're
    not needed beyond this point, so we don't need to worry
    about reconstructing them after the header file inclusion. */
/* some curses.h decl m_move(), not used here */
/* trust include file */
/* guess BGR */
/* guess RGB */
/* Mapping data for the six terminfo colors that resolve to pairs of nethack
 * colors.  Black and white are handled specially.
 */
function cl_eos()
{
    
    if (C.nh_CD) {
        xputs(C.nh_CD);
                    
        { let r; nomux_clear_to_eol(C.ttyDisplay.cury, C.ttyDisplay.curx); for (r = C.int(C.ttyDisplay.cury + 1); r < 24; r++) nomux_clear_to_eol(r, 0); }
      
    } else {
        let cy = C.int(C.ttyDisplay.cury + 1);

        while (cy <= C.LI - 2) {
            cl_end();
            void (xputc(10));
            cy++;
        }
        cl_end();
        C.tty_curs(C.BASE_WINDOW, C.int( C.ttyDisplay.curx) + 1,
                 C.int( C.ttyDisplay.cury));
    }
}

function init_hilite()
{
    
    let c; let colors;
    let setf; let scratch;

    colors = C.int(C.tgetnum(C.nhStr("Co")));
    C.iflags.colorcount = colors;
    let md_len = C.int(0);

    if (Number(Boolean(colors < 8 || !C.MD || !C.HEAP8[C.charPointer(C.MD)]
        || (C.pointerEqual((setf = C.charPointer(C.tgetstr(C.nhStr("AF"), ( 0)))),( 0))
            && C.pointerEqual((setf = C.charPointer(C.tgetstr(C.nhStr("Sf"), ( 0)))),( 0)))))) {
        /* Fallback when colors not available
         * It's arbitrary to collapse all colors except gray
         * together, but that's what the previous code did.
         */
        C.hilites[C.CLR_BLACK] = C.charPointer(C.nh_HI);
        C.hilites[C.CLR_RED] = C.charPointer(C.nh_HI);
        C.hilites[C.CLR_GREEN] = C.charPointer(C.nh_HI);
        C.hilites[C.CLR_BROWN] = C.charPointer(C.nh_HI);
        C.hilites[C.CLR_BLUE] = C.charPointer(C.nh_HI);
        C.hilites[C.CLR_MAGENTA] = C.charPointer(C.nh_HI);
        C.hilites[C.CLR_CYAN] = C.charPointer(C.nh_HI);
        C.hilites[C.CLR_GRAY] = C.charPointer(C.nilstring);
        C.hilites[C.NO_COLOR] = C.charPointer(C.nilstring);
        C.hilites[C.CLR_ORANGE] = C.charPointer(C.nh_HI);
        C.hilites[C.CLR_BRIGHT_GREEN] = C.charPointer(C.nh_HI);
        C.hilites[C.CLR_YELLOW] = C.charPointer(C.nh_HI);
        C.hilites[C.CLR_BRIGHT_BLUE] = C.charPointer(C.nh_HI);
        C.hilites[C.CLR_BRIGHT_MAGENTA] = C.charPointer(C.nh_HI);
        C.hilites[C.CLR_BRIGHT_CYAN] = C.charPointer(C.nh_HI);
        C.hilites[C.CLR_WHITE] = C.charPointer(C.nh_HI);
        return;
    }

    if (colors >= 16) {
        for (c = C.int(0); c < C.SIZE(C.ti_map); c++) {
            /* system colors */
            scratch = C.charPointer(C.tparm(setf, C.ti_map[c].nh_color));
            C.hilites[C.ti_map[c].nh_color] = C.charPointer(C.dupstr(scratch));
            /* bright colors */
            scratch = C.charPointer(C.tparm(setf, C.ti_map[c].nh_bright_color));
            C.hilites[C.ti_map[c].nh_bright_color] = C.charPointer(C.dupstr(scratch));
        }
    } else {
        /* 8 system colors */
        md_len = C.int(C.int( C.strlen(C.MD)));

        c = C.int(6);
        while (c--) {
            let work;

            scratch = C.charPointer(C.tparm(setf, C.ti_map[c].ti_color));
            work = C.charPointer(( C.alloc(C.ulong((C.ulong(C.ulong((C.ulong(C.strlen(scratch))) + (C.ulong(md_len))))) + (C.ulong(1))))));
            C.Strcpy(work, C.MD);
            C.hilites[C.ti_map[c].nh_bright_color] = C.charPointer(work);
            work = C.charPointer(work) + Number(md_len);
            C.Strcpy(work, scratch);
            C.hilites[C.ti_map[c].nh_color] = C.charPointer(work);
        }
    }

    if (colors >= 16) {
        scratch = C.charPointer(C.tparm(setf, C.COLOR_WHITE | C.BRIGHT));
        C.hilites[C.CLR_WHITE] = C.charPointer(C.dupstr(scratch));
    } else {
        scratch = C.charPointer(C.tparm(setf, C.COLOR_WHITE));
        C.hilites[C.CLR_WHITE] = C.charPointer(( C.alloc(C.ulong((C.ulong(C.ulong((C.ulong(C.strlen(scratch))) + (C.ulong(md_len))))) + (C.ulong(1))))));
        C.Strcpy(C.hilites[C.CLR_WHITE], C.MD);
        C.Strcat(C.hilites[C.CLR_WHITE], scratch);
    }

    C.hilites[C.CLR_GRAY] = C.charPointer(C.nilstring);
    C.hilites[C.NO_COLOR] = C.charPointer(C.nilstring);

    if (C.iflags.wc2_darkgray) {
        if (colors >= 16) {
            scratch = C.charPointer(C.tparm(setf, C.COLOR_BLACK|C.BRIGHT));
            C.hilites[C.CLR_BLACK] = C.charPointer(C.dupstr(scratch));
        } else {
            /* On many terminals, esp. those using classic PC CGA/EGA/VGA
            * textmode, specifying "hilight" and "black" simultaneously
            * produces a dark shade of gray that is visible against a
            * black background.  We can use it to represent black objects.
            */
            scratch = C.charPointer(C.tparm(setf, C.COLOR_BLACK));
            C.hilites[C.CLR_BLACK] = C.charPointer(( C.alloc(C.ulong((C.ulong(C.ulong((C.ulong(C.strlen(scratch))) + (C.ulong(md_len))))) + (C.ulong(1))))));
            C.Strcpy(C.hilites[C.CLR_BLACK], C.MD);
            C.Strcat(C.hilites[C.CLR_BLACK], scratch);
        }
    } else {
        /* But it's conceivable that hilighted black-on-black could
         * still be invisible on many others.  We substitute blue for
         * black.
         */
        C.hilites[C.CLR_BLACK] = C.charPointer(C.hilites[C.CLR_BLUE]);
    }
}

