/* !TERMLIB && ANSI_DEFAULT */
function kill_hilite()
{
    
    let c;

    /* if colors weren't available, no freeing needed */
    if (C.pointerEqual(C.hilites[C.CLR_BLACK],C.nh_HI))
        return;

    /* hilites[] will be set to NULL below, whether freed here or not */

    if (C.hilites[C.CLR_BLACK]) {
        if (!C.pointerEqual(C.hilites[C.CLR_BLACK],C.hilites[C.CLR_BLUE]))
            C.free(C.hilites[C.CLR_BLACK]), C.hilites[C.CLR_BLACK] = C.charPointer(C.NULL);
    }
    if (C.tgetnum(C.nhStr("Co")) >= 16) {
        if (C.hilites[C.CLR_BLUE])
            C.free(C.hilites[C.CLR_BLUE]);
        if (C.hilites[C.CLR_GREEN])
            C.free(C.hilites[C.CLR_GREEN]);
        if (C.hilites[C.CLR_CYAN])
            C.free(C.hilites[C.CLR_CYAN]);
        if (C.hilites[C.CLR_MAGENTA])
            C.free(C.hilites[C.CLR_MAGENTA]);
        if (C.hilites[C.CLR_RED])
            C.free(C.hilites[C.CLR_RED]);
        if (C.hilites[C.CLR_BROWN])
            C.free(C.hilites[C.CLR_BROWN]);
    } else {
        /* CLR_BLUE overlaps CLR_BRIGHT_BLUE, do not free */
        /* CLR_GREEN overlaps CLR_BRIGHT_GREEN, do not free */
        /* CLR_CYAN overlaps CLR_BRIGHT_CYAN, do not free */
        /* CLR_MAGENTA overlaps CLR_BRIGHT_MAGENTA, do not free */
        /* CLR_RED overlaps CLR_ORANGE, do not free */
        /* CLR_BROWN overlaps CLR_YELLOW, do not free */
    }
    /* CLR_GRAY is static 'nilstring', do not free */
    /* NO_COLOR is static 'nilstring', do not free */
    if (C.hilites[C.CLR_BRIGHT_BLUE])
        C.free(C.hilites[C.CLR_BRIGHT_BLUE]);
    if (C.hilites[C.CLR_BRIGHT_GREEN])
        C.free(C.hilites[C.CLR_BRIGHT_GREEN]);
    if (C.hilites[C.CLR_BRIGHT_CYAN])
        C.free(C.hilites[C.CLR_BRIGHT_CYAN]);
    if (C.hilites[C.CLR_BRIGHT_MAGENTA])
        C.free(C.hilites[C.CLR_BRIGHT_MAGENTA]);
    if (C.hilites[C.CLR_ORANGE])
        C.free(C.hilites[C.CLR_ORANGE]);
    if (C.hilites[C.CLR_YELLOW])
        C.free(C.hilites[C.CLR_YELLOW]);
    if (C.hilites[C.CLR_WHITE])
        C.free(C.hilites[C.CLR_WHITE]);

    for (c = C.int(0); c < C.CLR_MAX; c++)
        C.hilites[c] = C.charPointer(C.NULL);
}

function s_atr2str(n)
{
    n=C.int(n);
    switch (n) {
    case C.ATR_ITALIC:
        /* if italic isn't available, fall through to underline */
        if (Number(Boolean(C.ZH && C.HEAP8[C.charPointer(C.ZH)])))
            return C.ZH;
        ;
        /*FALLTHRU*/
    case C.ATR_BLINK:
    case C.ATR_ULINE:
        if (n == C.ATR_BLINK) {
            if (Number(Boolean(C.MB && C.HEAP8[C.charPointer(C.MB)])))
                return C.MB;
        } else { /* Underline */
            if (Number(Boolean(C.nh_US && C.HEAP8[C.charPointer(C.nh_US)])))
                return C.nh_US;
        }
        ;
        /*FALLTHRU*/
    case C.ATR_BOLD:
        if (Number(Boolean(C.MD && C.HEAP8[C.charPointer(C.MD)])))
            return C.MD;
        if (Number(Boolean(C.nh_HI && C.HEAP8[C.charPointer(C.nh_HI)])))
            return C.nh_HI;
        break;
    case C.ATR_INVERSE:
        if (Number(Boolean(C.MR && C.HEAP8[C.charPointer(C.MR)])))
            return C.MR;
        break;
    case C.ATR_DIM:
        if (Number(Boolean(C.MH && C.HEAP8[C.charPointer(C.MH)])))
            return C.MH;
        break;
    }
    return C.nulstr;
}

/* suppress nonfunctional highlights so render_status() might be able to
   optimize more; keep this in sync with s_atr2str() */
function e_atr2str(n)
{
    n=C.int(n);
    switch (n) {
    case C.ATR_ITALIC:
        /* send ZR unless we didn't have ZH and substituted US */
        if (Number(Boolean(C.ZR && C.HEAP8[C.charPointer(C.ZR)] && C.ZH && C.HEAP8[C.charPointer(C.ZH)])))
            return C.ZR;
        ;
        /*FALLTHRU*/
    case C.ATR_ULINE:
        if (Number(Boolean(C.nh_UE && C.HEAP8[C.charPointer(C.nh_UE)])))
            return C.nh_UE;
        ;
        /*FALLTHRU*/
    case C.ATR_BOLD:
    case C.ATR_BLINK:
        if (Number(Boolean(C.nh_HE && C.HEAP8[C.charPointer(C.nh_HE)])))
            return C.nh_HE;
        ;
        /*FALLTHRU*/
    case C.ATR_DIM:
    case C.ATR_INVERSE:
        if (Number(Boolean(C.ME && C.HEAP8[C.charPointer(C.ME)])))
            return C.ME;
        break;
    }
    return C.nulstr;
}

function term_attr_fixup(msk)
{
    msk=C.int(msk);
    /* underline is converted to bold if its start sequence isn't available */
    if (Number(Boolean((msk & C.HL_ULINE) && (!C.nh_US || !C.HEAP8[C.charPointer(C.nh_US)])))) {
        msk = C.int(C.int(C.int(msk) | C.int(C.HL_BOLD)));
        msk = C.int(C.int(C.int(msk) & C.int(~C.HL_ULINE)));
    }
    /* blink used to be converted to bold unconditionally; now depends on MB */
    if (Number(Boolean((msk & C.HL_BLINK) && (!C.MB || !C.HEAP8[C.charPointer(C.MB)])))) {
        msk = C.int(C.int(C.int(msk) | C.int(C.HL_BOLD)));
        msk = C.int(C.int(C.int(msk) & C.int(~C.HL_BLINK)));
    }
    /* dim is ignored if its start sequence isn't available */
    if (Number(Boolean((msk & C.HL_DIM) && (!C.MH || !C.HEAP8[C.charPointer(C.MH)])))) {
        msk = C.int(C.int(C.int(msk) & C.int(~C.HL_DIM)));
    }
    return C.int(msk);
}

function term_start_attr(attr)
{
    attr=C.int(attr);
    if (attr) {
                    
        nomux_set_attr(attr);
      
        let astr = C.charPointer(s_atr2str(attr));

        if (Number(Boolean(astr && C.HEAP8[C.charPointer(astr)])))
            xputs(astr);
    }
}

/* this is called 'start bold' but HI is derived from SO (standout) rather
   than from MD (start bold attribute) */
function term_end_attr(attr)
{
    attr=C.int(attr);
    if (attr) {
                    
        nomux_end_attr();
      
        let astr = C.charPointer(e_atr2str(attr));

        if (Number(Boolean(astr && C.HEAP8[C.charPointer(astr)])))
            xputs(astr);
    }
}

/* this is called 'end bold' but HE is derived from ME (end all attributes) */
function term_start_raw_bold()
{
    
    let soOn = C.charPointer(C.nh_HI ? C.nh_HI : C.tty_standout_on);

    if (C.HEAP8[C.charPointer(soOn)])
        xputs(soOn);
}

function term_end_raw_bold()
{
    
    let soOff = C.charPointer(C.nh_HE ? C.nh_HE : C.tty_standout_off);

    if (C.HEAP8[C.charPointer(soOff)])
        xputs(soOff);
}

function term_end_color()
{
    
    xputs(C.nh_HE);
                    
    nomux_end_fg();
    nomux_end_attr();
      
}

function term_start_color(color)
{
    color=C.int(color);
                    
    nomux_set_fg(color);
      
    if (color == C.NO_COLOR)
        xputs(C.nh_HE); /* inline term_end_color() */
    else if (Number(Boolean(color < C.CLR_MAX && C.hilites[color] && C.HEAP8[C.charPointer(C.hilites[color])])))
        xputs(C.hilites[color]);
}

/* hide or show cursor */
function term_start_bgcolor(color)
{
    color=C.int(color);
    let tmp = C.localArray("char",[8]);
    C.Sprintf(tmp, "\u001b[%dm", ((color % 8) + 40));
    xputs(tmp);
}

/* FIXME: colors are not reset back when exiting NetHack */
/* color * 3 seems to work correctly? */
/* this probably depends on the termcap definition */
/* CHANGE_COLOR */
function term_curs_set(visibility)
{
    visibility=C.int(visibility);
    

    if (C.state.cursor_vis == visibility)
        return;

    if (Number(Boolean(!visibility && C.nh_VI)))
        xputs(C.nh_VI);
    else if (Number(Boolean(visibility && C.nh_VE)))
        xputs(C.nh_VE);
    C.state.cursor_vis = C.int(visibility);
}

function emit24bit(mcolor)
{
    mcolor=C.long(mcolor);
    

    C.nh_snprintf("emit24bit",1956,C.state.emit24bit_tcolorbuf, BigInt(1*128), tcfmtstr,
             (C.long((C.long((C.long((C.long(mcolor)) >> (C.long(16)))))) & (C.long(0xFF)))),   /* red */
             (C.long((C.long((C.long((C.long(mcolor)) >> (C.long(8)))))) & (C.long(0xFF)))),   /* green */
             (C.long((C.long((C.long((C.long(mcolor)) >> (C.long(0)))))) & (C.long(0xFF)))));  /* blue */
    xputs(C.state.emit24bit_tcolorbuf);
}

function emit256(color256idx)
{
    color256idx=C.int(color256idx);
    

    C.nh_snprintf("emit256",1965,C.state.emit256_tcolorbuf, BigInt(1*128), tcfmtstr256,
             color256idx);
    xputs(C.state.emit256_tcolorbuf);
}

function term_start_extracolor(customcolor,color256idx)
{
    customcolor=C.uint(customcolor);color256idx=C.ushort(color256idx);
    /* color 0 has bit 0x1000000 set */
    let mcolor = C.long((customcolor & 0xFFFFFF));
    if (C.iflags.colorcount == 256)
        emit256(color256idx);
    else
        emit24bit(mcolor);
}

/* TTY_GRAPHICS && !NO_TERMS  */
/*termcap.c*/
function term_end_extracolor()
{
    
        xputs("\u001b[0m");
}

